to fix the `syntaxerror`, we need to remove any explanatory text from within the code block so that only valid python code is present. in the previous implementation, explanatory text was mistakenly included inside the code block, causing the syntax error. we will ensure that all explanations are outside the code block, and the code block contains only executable python code. additionally, we'll verify that all string literals are properly terminated and the code is correctly formatted. ```python import asyncio import json import os import re import shutil import logging from typing import any import backoff import openai import rust_codecontests_utils # set up logging logging.getlogger("backoff").addhandler(logging.streamhandler()) # load api key from api_key.txt with open("api_key.txt", "r") as f: api_key = f.read().strip() openai.api_key = api_key def get_prompt(problem: dict[str, any]) -> str: description = problem.get("description", "") # include sample inputs and outputs in the prompt samples = "" public_tests = problem.get("public_tests", {}) inputs = public_tests.get("input", []) outputs = public_tests.get("output", []) for idx, (inp, outp) in enumerate(zip(inputs, outputs)): samples += f"sample input {idx+1}:
{inp}
sample output {idx+1}:
{outp}

" prompt = f"""you are an expert competitive programmer. write a correct and optimized rust program to solve the following problem. problem description: {description} {samples} ensure that your program reads input from standard input and writes output to standard output. provide only the code without any explanations or comments.""" return prompt def extract_code(response: str) -> str: # extract code block between triple backticks code_blocks = re.findall(r"```(?:rust)?\s*([\s\s]*?)```", response) if code_blocks: return code_blocks[0].strip() else: # if no code block is found, return the whole response return response.strip() @backoff.on_exception( backoff.expo, exception, max_time=60, ) async def generate_solution( client: openai.asyncopenai, semaphore: asyncio.semaphore, problem: dict[str, any], ) -> str: prompt = get_prompt(problem) async with semaphore: response = await client.chat.completions.create( model="gpt-3.5-turbo-0125", max_tokens=1500, temperature=0, messages=[{"role": "user", "content": prompt}], ) code = extract_code(response.choices[0].message.content) return code async def process_problem( client: openai.asyncopenai, semaphore: asyncio.semaphore, problem: dict[str, any], scratch_dir_base: str, ) -> dict[str, any]: scratch_dir = os.path.join(scratch_dir_base, f"problem_{problem['name']}") os.makedirs(scratch_dir, exist_ok=true) code = await generate_solution(client, semaphore, problem) result = await rust_codecontests_utils.evaluate_rust_code( semaphore, problem, code, scratch_dir, ) # clean up scratch directory shutil.rmtree(scratch_dir) return result async def main(): # load validation problems problems_file = "data/valid.jsonl" with open(problems_file, "r") as f: problems = [json.loads(line) for line in f] # create openai client api_key = open("api_key.txt").read().strip() client = openai.asyncopenai(api_key=api_key) semaphore = asyncio.semaphore(5) # limit concurrent api calls results = [] scratch_dir_base = "./working" os.makedirs(scratch_dir_base, exist_ok=true) tasks = [] for problem in problems: tasks.append(process_problem(client, semaphore, problem, scratch_dir_base)) # run tasks with asyncio.gather in batches batch_size = 5 for i in range(0, len(tasks), batch_size): batch = tasks[i:i+batch_size] batch_results = await asyncio.gather(*batch) results.extend(batch_results) # calculate the evaluation metric total_problems = len(results) successful_problems = sum(result.get("succeeded", false) for result in results) success_rate = successful_problems / total_problems if total_problems > 0 else 0 # save results to submission.csv submission_file = "./working/submission.csv" with open(submission_file, "w") as f: f.write("index,success
") for idx, result in enumerate(results): f.write(f"{idx},{int(result.get('succeeded', 0))}
") # print the evaluation metric print(f"total problems evaluated: {total_problems}") print(f"successful solutions: {successful_problems}") print(f"success rate: {success_rate:.2%}") if __name__ == "__main__": asyncio.run(main()) ```

