{input_sample}
" f"sample output {idx + 1}:
{output_sample}

" ) prompt = f"""you are participating in a competitive programming contest. please solve the following problem in rust. problem description: {description} input format: {input_format} output format: {output_format} {sample_tests_section} please write a complete, efficient, and correct rust program that reads from standard input and writes to standard output. the program should not include any unnecessary output or debug statements. make sure to handle all edge cases and consider efficient algorithms and data structures. use rust 2018 edition.""" return prompt @backoff.on_exception( backoff.expo, exception, max_time=300, ) async def generate_solution( client: any, semaphore: asyncio.semaphore, problem: dict[str, any], ) -> str: prompt = get_prompt(problem) async with semaphore: response = await client.chatcompletion.acreate( model="gpt-3.5-turbo-0125", max_tokens=1600, temperature=0, messages=[{"role": "user", "content": prompt}], ) completion = response.choices[0].message.content return completion async def main(): import json import rust_codecontests_utils as utils import os from tqdm.asyncio import tqdm # load the validation problems with open("data/valid.jsonl", "r") as f: problems = [json.loads(line) for line in f] # set up openai api key openai.api_key = open("api_key.txt").read().strip() # set up a semaphore to limit concurrency semaphore = asyncio.semaphore(5) # create a scratch directory for code evaluation scratch_dir = "./scratch" os.makedirs(scratch_dir, exist_ok=true) # generate and evaluate solutions results = [] for problem in tqdm(problems, desc="processing problems"): code = await generate_solution(openai, semaphore, problem) result = await utils.evaluate_rust_code(semaphore, problem, code, scratch_dir) results.append(result) # clean up scratch directory for filename in os.listdir(scratch_dir): os.remove(os.path.join(scratch_dir, filename)) # compute the evaluation metric successes = [r for r in results if r["succeeded"]] success_ratio = len(successes) / len(results) print(f"validation metric: {success_ratio}") if __name__ == "__main__": asyncio.run(main()) ```

