mpt with few-shot examples def get_few_shot_prompt(problem: dict[str, any], examples: list[dict[str, any]]) -> str: prompt = "here are some examples of coding contest problems and their solutions in rust:
" for idx, ex in enumerate(examples): prompt += f"
problem {idx+1}:
{ex['description']}

solution {idx+1}:
{ex['solution']}
{'-'*40}
" prompt += f"
now, please solve the following problem in rust:
{problem['description']}
" return prompt @backoff.on_exception( backoff.expo, exception, max_time=300, ) async def generate_solution( client: openai.asyncopenai, semaphore: asyncio.semaphore, problem: dict[str, any], ) -> str: # load examples inside the function examples = load_few_shot_examples(num_examples=3) prompt = get_few_shot_prompt(problem, examples) async with semaphore: completion = ( ( await client.chat.completions.create( model="gpt-3.5-turbo-0125", max_tokens=1600, temperature=0.7, messages=[{"role": "user", "content": prompt}], ) ) .choices[0] .message.content ) return completion async def evaluate_problem( client: openai.asyncopenai, semaphore: asyncio.semaphore, problem: dict[str, any], ) -> dict[str, any]: try: generated_code = await generate_solution(client, semaphore, problem) # evaluate the generated code result = await evaluate_rust_code( semaphore, problem, generated_code, "./working" ) except exception as error: result = {"succeeded": false, "error": str(error)} return result async def main(): # load validation problems with open("./data/valid.jsonl", "r") as f: problems = [json.loads(line) for line in f.readlines()] semaphore = asyncio.semaphore(5) successes = 0 total = len(problems) results = [] async with openai.asyncopenai(api_key=openai.api_key) as client: tasks = [] for problem in problems: tasks.append(evaluate_problem(client, semaphore, problem)) results = await asyncio.gather(*tasks, return_exceptions=false) # save the results to submission.csv os.makedirs("./working", exist_ok=true) with open("./working/submission.csv", "w", newline="", encoding="utf-8") as csvfile: fieldnames = ["problem_name", "succeeded"] writer = csv.dictwriter(csvfile, fieldnames=fieldnames) writer.writeheader() for problem, result in zip(problems, results): if isinstance(result, dict): succeeded = result.get("succeeded", false) writer.writerow( {"problem_name": problem["name"], "succeeded": succeeded} ) if succeeded: successes += 1 success_rate = successes / total print(f"validation metric (success rate): {success_rate}") if __name__ == "__main__": asyncio.run(main()) ```

