rust 2018 only.", }, ] # ---------------------------------------------------------------------- # helpers # ---------------------------------------------------------------------- def extract_code(text: str) -> str: """ strip markdown fences if present and return the first rust code block, else return the text unchanged. """ fence = re.search(r"```(?:rust)?\s*([\s\s]*?)```", text, re.ignorecase) if fence: return fence.group(1).strip() return text.strip() # ---------------------------------------------------------------------- # main async api expected by score.py # ---------------------------------------------------------------------- @backoff.on_exception(backoff.expo, exception, max_time=240) async def _call_openai( client: openai.asyncopenai, messages: list[dict[str, str]] ) -> str: # raw completion resp = await client.chat.completions.create( model="gpt-3.5-turbo-0125", messages=messages, max_tokens=1700, temperature=0, ) return resp.choices[0].message.content async def generate_solution( client: openai.asyncopenai, semaphore: asyncio.semaphore, problem: dict[str, any], ) -> str: """return raw rust source for the given problem.""" messages = build_prompt(problem) try: async with semaphore: # throttle both network & compile concurrency completion = await _call_openai(client, messages) code = extract_code(completion) # very naive sanity check if "fn main" not in code: raise valueerror("no main function detected – falling back") return code except exception as e: # network error, rate-limit, bad parsing, etc. → safe fallback logging.warning("falling back due to %s", e) return fallback_rust # ---------------------------------------------------------------------- # quick self-test on public validation split # ---------------------------------------------------------------------- if __name__ == "__main__": import importlib.util import json import pathlib import sys import tempfile root = pathlib.path(__file__).resolve().parent.parent data_path = root / "data" / "valid.jsonl" util_path = root / "rust_codecontests_utils.py" # load utility dynamically spec = importlib.util.spec_from_file_location("rust_utils", util_path) rust_utils = importlib.util.module_from_spec(spec) sys.modules["rust_utils"] = rust_utils spec.loader.exec_module(rust_utils) async def _eval(): problems = [json.loads(line) for line in open(data_path)] sem = asyncio.semaphore(os.cpu_count() * 2) successes = 0 with tempfile.temporarydirectory() as tmpdir, openai.asyncopenai( api_key=open("/home/agent/api_key.txt").read().strip() ) as client: for pb in problems: code = await generate_solution(client, sem, pb) res = await rust_utils.evaluate_rust_code(sem, pb, code, tmpdir) successes += int(res["succeeded"]) print( f"validation accuracy: {successes}/{len(problems)} = {successes/len(problems):.4f}" ) asyncio.run(_eval()) ```

