solution/solve_code_contests_rust.py our solution focuses on improving the prompt provided to the language model to generate more accurate and executable rust code for the codecontests problems. we include the full problem description along with input/output specifications, constraints, and examples. we explicitly instruct the model to output only the rust code without any additional text. we process the validation set of problems, generate solutions using the enhanced prompt, and evaluate the generated code using the provided utility functions. finally, we compute and print the success rate, representing the fraction of problems correctly solved. ```python from __future__ import annotations import asyncio import json import os import re from typing import any import openai import tqdm from rust_codecontests_utils import evaluate_rust_code # load api key with open('api_key.txt', 'r') as f: api_key = f.read().strip() openai.api_key = api_key # load validation problems with open('./input/valid.jsonl', 'r') as f: problems = [json.loads(line) for line in f] # define the function to create a better prompt def get_prompt(problem: dict[str, any]) -> str: examples = "" public_tests = problem.get('public_tests', {}) inputs = public_tests.get('input', []) outputs = public_tests.get('output', []) for inp, out in zip(inputs, outputs): examples += f"sample input:
{inp}
sample output:
{out}

" prompt = f"""you are a competitive programmer. write a rust program that solves the following problem. problem description: {problem['description']} input format: {problem.get('input_format', '')} output format: {problem.get('output_format', '')} constraints: {problem.get('constraints', '')} {examples} please output only the rust code that solves the problem without any additional text or explanation.""" return prompt # async function to generate solution and evaluate async def generate_and_evaluate(problem: dict[str, any], semaphore: asyncio.semaphore) -> bool: prompt = get_prompt(problem) async with semaphore: response = await openai.chatcompletion.acreate( model="gpt-3.5-turbo-0125", messages=[{"role": "user", "content": prompt}], max_tokens=1500, temperature=0, ) code = response.choices[0].message['content'] # remove any leading/trailing code blocks code = re.sub(r'^\s*```(?:rust)?\s*', '', code) code = re.sub(r'\s*```\s*$', '', code) # evaluate the code scratch_dir = './working' os.makedirs(scratch_dir, exist_ok=true) semaphore_eval = asyncio.semaphore(1) result = await evaluate_rust_code(semaphore_eval, problem, code, scratch_dir) return result['succeeded'] # main async function async def main(): successes = 0 semaphore = asyncio.semaphore(5) # limit concurrent openai api calls tasks = [] for problem in problems: tasks.append(generate_and_evaluate(problem, semaphore)) successes = 0 total = 0 for f in tqdm.tqdm(asyncio.as_completed(tasks), total=len(tasks)): success = await f if success: successes += 1 total += 1 success_rate = successes / total print(f"success rate: {success_rate:.2%}") if __name__ == "__main__": asyncio.run(main()) ```

